function m(n){if(n.length===0)return[];const t=[...new Set(n)].sort((o,e)=>o-e),r=new Map;return t.forEach((o,e)=>r.set(o,e)),n.map(o=>r.get(o))}function c(n){const t=n.length,r=Array.from({length:t},()=>Array(t).fill("0"));for(let o=0;o<t;o++)for(let e=0;e<t;e++)n[e]>n[o]?r[o][e]="+":n[e]<n[o]?r[o][e]="-":r[o][e]="0";return r}function p(n){const t=[];for(let r=0;r<n.length-1;r++)n[r+1]>n[r]?t.push("+"):n[r+1]<n[r]?t.push("-"):t.push("0");return t}function s(n){if(n.length===0)return[];const t=Math.max(...n);return n.map(r=>t-r)}function d(n){return[...n].reverse()}function y(n){return d(s(n))}function x(n){const t=n.length;for(let r=0;r<Math.floor(t/2);r++)if(n[r]!==n[t-1-r])return!1;return!0}function M(n,t){if(n.length!==t.length)return!1;for(let r=0;r<n.length;r++)if(n[r]!==t[r])return!1;return!0}function g(n){return M(n,s(n))}function S(n,t){if(n.length!==t.length||n.length<2)return 0;const r=c(n),o=c(t),e=n.length;let a=0,f=0;for(let l=0;l<e;l++)for(let i=l+1;i<e;i++)f++,r[l][i]===o[l][i]&&a++;return f===0?1:a/f}function v(n){let t=0;for(let r=0;r<n.length-1;r++){const o=Math.abs(n[r+1]-n[r]);o>t&&(t=o)}return t}function j(n){if(n.length===0)return"c0-000";const t=m(n),r=s(t),o=d(t),e=y(t),l=[t,r,o,e].sort((i,h)=>{for(let u=0;u<i.length;u++)if(i[u]!==h[u])return i[u]-h[u];return 0})[0].join("");return`c${n.length}-${l}`}function A(n){const t=m(n);return{cseg:t,comMatrix:c(t),cas:p(t),isPalindrome:x(t),isInversionallySymmetric:g(t),depth:v(t)}}export{A as a,S as b,j as c,y as d,d as e,s as f,m as t};
